def count_different_sums(x1, y1, x2, y2):
    return len(set(range((x2 - x1 + 1) + (y2 - y1 + 1))))

t = int(input())
results = []
for _ in range(t):
    x1, y1, x2, y2 = map(int, input().split())
    results.append(count_different_sums(x1, y1, x2, y2))

for result in results:
    print(result)
